import pytest

def func(nums, k):
    import collections
    d = collections.defaultdict(int)
    for row in nums:
        for i in row:
            d[i] += 1
    temp = []
    import heapq
    for key, v in d.items():
        if len(temp) < k:
            temp.append((v, key))
            if len(temp) == k:
                heapq.heapify(temp)
        else:
            if v < temp[0][0]:
                heapq.heappop(temp)
                heapq.heappush(temp, (v, key))
    result = []
    while temp:
        v, key = heapq.heappop(temp)
        result.append(key)
    return result

# Test case with incorrect output due to heap size limit
@pytest.mark.parametrize("nums", [
    ([[4, 6, 2], [3, 5]], 3),
    ([[1, 2, 2, 3], [4, 5, 6]], 2)
])
def test_func(nums, k):
    assert func(nums, k) != [1, 2, 2]
